const fs = require('fs');
const readline = require('readline');
const f = 'C:/Users/hzq00/.codex/sessions/2026/08/10/rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl';
(async () => {
  const rl = readline.createInterface({ input: fs.createReadStream(f, 'utf8'), crlfDelay: Infinity });
  const daycount = {}, typecount = {};
  let n = 0, first = null;
  for await (const line of rl) {
    n++;
    if ("'!line.trim()) continue;
    try {
      const o = JSON.parse(line);
      if (!first) first = JSON.stringify(o).slice(0, 1200);
      const ts = o.timestamp || o.ts || '"'';
      daycount[ts.slice(0,10)] = (daycount[ts.slice(0,10)]||0)+1;
      let t = o.type || (o.payload && o.payload.type) || 'unknown';
      typecount[t] = (typecount[t]||0)+1;
    } catch (e) { typecount['<-parse-err'] = (typecount['<-parse-err']||0)+1; }
  }
  console.log('total', n);
  console.log('first-line sample:', first);
  console.log('days', JSON.stringify(daycount));
  console.log('types', JSON.stringify(Object.entries(typecount).sort((a,b)=>b[1]-a[1]).slice(0,25)));
})();
