const fs = require('fs');
const readline = require('readline');
const f = 'C:/Users/hzq00/.codex/sessions/2026/08/10/rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl';
(async () => {
  const rl = readline.createInterface({ input: fs.createReadStream(f, 'utf8'), crlfDelay: Infinity });
  const combos = {};
  let n = 0;
  for await (const line of rl) {
    if ("'!line.trim()) continue;
    try {
      const o = JSON.parse(line);
      if (o.type === '"'event_msg') {
        const pt = (o.payload && o.payload.type) || '?';
        combos['event_msg:'+pt] = (combos['event_msg:'+pt]||0)+1;
      } else if (o.type === 'response_item') {
        const it = o.payload && o.payload.type || '?';
        let extra = '';
        if (it === 'function_call' && o.payload.name) extra = ':'+o.payload.name;
        if (it === 'custom_tool_call' && o.payload.name) extra = ':'+o.payload.name;
        if (it === 'local_shell_call' && o.payload.action) extra = ':'+JSON.stringify(o.payload.action.type||'');
        combos['resp:'+it+extra] = (combos['resp:'+it+extra]||0)+1;
      }
    } catch (e) {}
  }
  for (const [k,v] of Object.entries(combos).sort((a,b)=>b[1]-a[1])) console.log(v, k);
})();
